import {drawReferencePlan} from './reference-plan.js';
import {drawNativeFootprint} from './native-map-image.js';
import { MAPS,activeMap } from './layout.js';
const $=id=>document.getElementById(id);
export function drawBlueprint(canvas,map){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,b=map.bounds,pad=18,s=Math.min((w-pad*2)/(b.maxX-b.minX),(h-pad*2)/(b.maxZ-b.minZ)),ox=(w-(b.maxX-b.minX)*s)/2,oy=(h-(b.maxZ-b.minZ)*s)/2,x=v=>ox+(v-b.minX)*s,z=v=>oy+(v-b.minZ)*s;
 ctx.fillStyle='#0b2330';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#24404a';ctx.lineWidth=.5;for(let xx=b.minX;xx<b.maxX;xx+=10){ctx.beginPath();ctx.moveTo(x(xx),oy);ctx.lineTo(x(xx),h-oy);ctx.stroke()}for(let zz=b.minZ;zz<b.maxZ;zz+=10){ctx.beginPath();ctx.moveTo(ox,z(zz));ctx.lineTo(w-ox,z(zz));ctx.stroke()}
 drawNativeFootprint(ctx,map,ox,oy,(b.maxX-b.minX)*s,(b.maxZ-b.minZ)*s);drawReferencePlan(ctx,map,ox,oy,(b.maxX-b.minX)*s,(b.maxZ-b.minZ)*s,{stations:false});
 const rect=o=>ctx.fillRect(x(o.x-o.w/2),z(o.z-o.d/2),o.w*s,o.d*s);ctx.fillStyle=map.palette.accent+'55';map.platforms.forEach(rect);ctx.fillStyle=map.palette.accent+'88';map.ramps.forEach(rect);ctx.strokeStyle='#b3c8c4';for(const path of map.paths){ctx.lineWidth=path.width*s*.55;ctx.beginPath();path.points.forEach((p,i)=>i?ctx.lineTo(x(p[0]),z(p[1])):ctx.moveTo(x(p[0]),z(p[1])));if(path.closed)ctx.closePath();ctx.stroke()}ctx.fillStyle='#354e58';[...map.buildings,...map.cover,...map.walls,...map.architecture].forEach(rect);ctx.fillStyle='#debf79';if(!map.reference)map.gates.forEach(rect);ctx.strokeStyle='#799caa';ctx.lineWidth=1;ctx.strokeRect(ox,oy,(b.maxX-b.minX)*s,(b.maxZ-b.minZ)*s);ctx.fillStyle='#c4ef9d';ctx.beginPath();ctx.arc(x(map.start.x),z(map.start.z),3,0,Math.PI*2);ctx.fill();for(const p of map.platforms){ctx.font='9px Arial';ctx.textAlign='center';ctx.fillStyle='#e2f5f7';ctx.fillText('+'+p.h+'m',x(p.x),z(p.z)+3)}
}
export function initMapMenu(onSelect){const list=$('mission-options');
 function render(){list.replaceChildren();for(const map of [...MAPS].filter(m=>m.reference||$('legacy-maps').checked||m.id===activeMap.id).sort((a,b)=>Number(!!b.reference)-Number(!!a.reference))){const card=document.createElement('button');card.className='mission-card'+(map.id===activeMap.id?' selected':'');card.style.setProperty('--map-accent',map.palette.accent);card.setAttribute('aria-pressed',String(map.id===activeMap.id));card.innerHTML=`<div class="mission-card-top"><span>${map.biome}</span><b>${map.id===activeMap.id?'SELECTED':'SELECT MAP'}</b></div><canvas width="480" height="260" aria-label="${map.name} route and elevation diagram"></canvas><div class="mission-card-body"><h3>${map.name}</h3><strong>${map.title}</strong><p>${map.description}</p><div class="mission-facts"><span>${map.reference?'2 floors / 3 barriers':map.native?'Original region':'Legacy prototype'}</span><span>${map.reference?'Measured source layout':map.native?'1:1 game scale':'Up to +'+map.elevation+'m'}</span><span>${map.difficulty}</span></div><small>${map.route}</small><div class="mission-enemies">${map.enemyNames.map(n=>`<span>${n}</span>`).join('')}</div></div>`;drawBlueprint(card.querySelector('canvas'),map);card.onclick=async()=>{list.querySelectorAll('button').forEach(b=>b.disabled=true);$('mission-status').textContent='Loading '+map.name+'...';try{await onSelect(map);close()}catch(e){$('mission-status').textContent=e.message;render()}};list.appendChild(card)}
 $('selected-map-name').textContent=activeMap.name;$('selected-map-subtitle').textContent=activeMap.title+' / Change map';$('mission-status').textContent='Dexlabs Bunker is the source-based rebuild. Earlier maps are retained as legacy prototypes.';
 }
 function open(){render();$('mission-select').classList.remove('hidden');list.querySelector('.selected')?.focus()}
 function close(){$('mission-select').classList.add('hidden');$('map-button').focus()}
 $('legacy-maps').onchange=render;$('map-button').onclick=open;$('close-mission-select').onclick=close;render();return {open,close,render};
}
